function sanitizeState(raw) {
 const validIds = v => Array.isArray(v) ? [...new Set(v.filter(x => typeof x === 'string' && Object.hasOwn(byId,x)))] : [];
 const notes = {};
 if (raw?.notes && typeof raw.notes === 'object' && !Array.isArray(raw.notes)) for (const [id, note] of Object.entries(raw.notes)) if (Object.hasOwn(byId,id) && typeof note === 'string') notes[id] = note.slice(0,20000);
 return {read:validIds(raw?.read),bookmarks:validIds(raw?.bookmarks),notes,last:typeof raw?.last === 'string' && Object.hasOwn(byId,raw.last) ? raw.last : ''};
}
let state;
try {state = sanitizeState(JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}')); localStorage.setItem(STORAGE_KEY,JSON.stringify(state));} catch {state = sanitizeState({});storageAvailable=false;}
const save = () => {try {localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageAvailable=true;} catch {storageAvailable=false;toast('浏览器存储不可用，请导出学习记录备份。');}};
