function route(){const hash=location.hash.replace(/^#\/?/,'');const [path,query='']=hash.split('?');return {parts:path.split('/').filter(Boolean),params:new URLSearchParams(query)};}
function link(id){return `#/lesson/${encodeURIComponent(id)}`;}
