 const active=key==='lesson'?(byId[currentRoute.parts[1]]?.kind==='pattern'?'scenarios':byId[currentRoute.parts[1]]?.kind==='foundation'?'path':'library'):key;
 document.title=`${getLabel()} · Agent 工程手册`;
 document.getElementById('app').innerHTML=`<aside class="sidebar" id="sidebar"><a class="brand" href="#/home"><span class="brand-mark">${icon('cube')}</span><span><span class="brand-name">Agent 工程手册</span><small>JAVA → AGENT</small></span></a><div class="nav-label">学习空间</div><nav aria-label="主要导航">${nav(active)}</nav><div class="nav-label" style="margin-top:18px">个人工具</div><nav aria-label="学习工具"><a class="nav-link ${active==='saved'?'active':''}" href="#/saved">${icon('bookmark')}我的学习</a><a class="nav-link ${active==='glossary'?'active':''}" href="#/glossary">${icon('book')}术语速查</a></nav><div class="sidebar-bottom"><div class="progress-box" id="sidebar-progress">${progressMarkup()}</div><div class="local-indicator"><span class="dot"></span>本地学习 · 无需模型 API Key</div></div></aside><div class="mobile-scrim" data-action="close-menu"></div><div class="shell"><header class="topbar"><button class="menu-toggle" data-action="menu" aria-label="打开导航" aria-expanded="false">${icon('menu')}</button><div class="breadcrumb"><span>学习空间</span>${icon('chevron')}<strong>${escape(getLabel())}</strong></div><div class="top-actions"><button class="search-trigger" data-action="search" aria-label="搜索全部文章与工程问答">${icon('search')}<span>搜索知识、组件或问题</span><kbd>⌘ K</kbd></button><span class="version"><span class="dot"></span>JAVA DEVELOPER EDITION</span></div></header><main class="main" id="main" tabindex="-1">${!storageAvailable?'<div class="storage-warning">当前浏览器无法持久化记录，阅读不受影响。可以在“我的学习”中导出备份。</div>':''}${content}<footer class="footer"><span>Agent 工程手册 · 把原理讲透，把组件用对。</span><span>资料核验：2026.10.14 · <a href="#/glossary">术语速查</a> · <a href="#/saved">本地记录与备份</a></span></footer></main></div>`;
