function renderScenarios(){return intro('CONNECT THE BUILDING BLOCKS','让组件在真实场景里协作','从一个具体需求出发，看清组件职责、数据流、失败处理和扩容边界。每个方案都从能交付的最小架构开始。')+`<div class="pattern-grid">${patterns.map((p,i)=>`<article class="pattern-card"><div class="section-heading"><span class="pattern-number">0${i+1}</span><span class="tag">场景拆解</span></div><h2>${escape(p.title)}</h2><p>${escape(p.summary)}</p><div class="related">${p.related.slice(0,4).filter(id=>byId[id]).map(id=>`<a class="tag" href="${link(id)}">${escape(byId[id].title)}</a>`).join('')}</div><a class="button" href="${link(p.id)}">拆解这个方案 ${icon('arrow')}</a></article>`).join('')}</div>`;}
function lessonSections(l){const fixed=[['overview','先建立直觉'],['scenarios','什么时候使用'],['flow','它在链路里的位置']];return [...fixed,...(demoById[l.id]?[['demos','接入 / 核心 / 场景 Demo']]:[]),...(scenarioRecipes[l.id]?[['scenario-code','场景中的核心代码']]:[]),...l.sections.map((s,i)=>[`section-${i}`,s.title]),['selection','怎么做取舍'],['pitfalls','容易踩的坑'],['questions','工程问答'],['notes','我的笔记'],['references','官方资料与延伸']];}
function renderLesson(l){if(!l)return renderNotFound();state.last=l.id;save();const read=state.read.includes(l.id),saved=state.bookmarks.includes(l.id);const position=ordered.findIndex(x=>x.id===l.id),prev=ordered[position-1],next=ordered[position+1];return `<div class="lesson-layout"><article class="lesson-article"><header class="lesson-header"><a class="text-link" href="#/${l.kind==='pattern'?'scenarios':l.kind==='foundation'?'path':'library'}">← 返回${l.kind==='pattern'?'场景架构':l.kind==='foundation'?'学习路线':'中间件图鉴'}</a><div class="tags"><span class="tag">${escape(l.category)}</span><span class="tag neutral">${escape(l.level)}</span><span class="tag blue">${escape(l.priority)}知识</span></div><h1>${escape(l.title)}</h1><p class="lead">${escape(l.summary)}</p><div class="meta"><span>${icon('clock')}约 ${l.minutes} 分钟</span><span>${icon('code')}面向 Java 工程实践</span><span>核验于 2026.10.14</span></div><div class="actions"><button class="button small ${read?'green':'primary'}" data-action="read" data-id="${l.id}">${icon(read?'check':'book')}${read?'已读 · 点击撤销':'标记为已读'}</button><button class="button small" data-action="bookmark" data-id="${l.id}">${icon('bookmark')}${saved?'已收藏':'收藏文章'}</button><button class="button small" data-action="copy-link">${icon('link')}复制链接</button>${demoById[l.id]?`<a class="button small green" href="#demos" data-action="scroll" data-target="demos">${icon('code')}查看三层 Demo</a>`:scenarioRecipes[l.id]?`<a class="button small green" href="#scenario-code" data-action="scroll" data-target="scenario-code">${icon('code')}查看场景核心代码</a>`:''}</div></header><section class="lesson-block" id="overview"><h2>先建立直觉</h2><div class="concept-grid">${l.concepts.map(c=>`<div class="concept"><h3>${escape(c.title)}</h3><p>${escape(c.text)}</p></div>`).join('')}</div></section><section class="lesson-block" id="scenarios"><h2>什么时候使用</h2><div class="use-grid"><div class="use-panel"><h3>${icon('check')}适合这些需求</h3><ul>${l.when.map(t=>`<li>${escape(t)}</li>`).join('')}</ul></div><div class="use-panel"><h3>${icon('info')}先别急着引入</h3><ul>${l.notFor.map(t=>`<li>${escape(t)}</li>`).join('')}</ul></div></div></section><section class="lesson-block" id="flow"><h2>它在链路里的位置</h2><div class="flow" role="list">${l.flow.map((s,i)=>`${i?'<span class="flow-arrow" aria-hidden="true">→</span>':''}<div class="flow-node" role="listitem">${escape(s)}</div>`).join('')}</div></section>${renderDemoSection(l.id,currentRoute.params.get('demo'))}${renderRecipe(l.id)}${l.sections.map((s,i)=>`<section class="lesson-block" id="section-${i}"><h2>${escape(s.title)}</h2>${(s.paragraphs||[]).map(p=>`<p>${escape(p)}</p>`).join('')}${s.bullets?.length?`<ul>${s.bullets.map(b=>`<li>${escape(b)}</li>`).join('')}</ul>`:''}${s.code?`<div class="code-block"><div class="code-head"><span>${escape(s.code.label)} · ${escape(s.code.language)}</span><button class="copy-code" data-action="copy-code" data-id="${l.id}" data-index="${i}">${icon('copy')}复制</button></div><pre><code>${escape(s.code.value)}</code></pre></div>`:''}</section>`).join('')}<section class="lesson-block" id="selection"><h2>怎么做取舍</h2><div class="table-scroll"><table class="decision-table"><thead><tr><th>选项</th><th>适用条件</th><th>需要承担的取舍</th></tr></thead><tbody>${l.decisions.map(d=>`<tr><td>${escape(d.option)}</td><td>${escape(d.fit)}</td><td>${escape(d.tradeoff)}</td></tr>`).join('')}</tbody></table></div>${l.kind==='middleware'?`<p style="margin-top:12px"><a class="text-link" href="#/compare?a=${l.id}">与其他组件并排比较 ${icon('arrow')}</a></p>`:''}</section><section class="lesson-block" id="pitfalls"><h2>容易踩的坑</h2><div class="callout"><ul>${l.pitfalls.map(p=>`<li>${escape(p)}</li>`).join('')}</ul></div></section><section class="lesson-block" id="questions"><h2>工程问答</h2>${l.qa.map((q,i)=>questionMarkup({...q,lesson:l,index:i},false)).join('')}</section><section class="lesson-block" id="notes"><h2>我的笔记</h2><p>记录你所在项目的约束、选型理由或排查思路。笔记只保存在当前浏览器，可在“我的学习”导出备份。</p><textarea class="note-area" data-note="${l.id}" maxlength="20000" aria-label="${escape(l.title)}的学习笔记" placeholder="例如：我们的知识库需要按租户过滤，现有 PostgreSQL 可以先承接……">${escape(state.notes[l.id]||'')}</textarea><div class="note-status" id="note-status">${state.notes[l.id]?'已从本地恢复笔记':'输入后自动保存在本地'}</div></section><section class="lesson-block" id="references"><h2>官方资料与延伸</h2><div class="source-list">${l.sources.map(s=>`<a class="source-link" href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.label)}${icon('external')}</a>`).join('')}</div><p style="font-size:11px;margin-top:13px;color:#8b987e">外部文档需要联网；示例的依赖和运行前提以正文说明为准，生产接入请匹配实际部署版本。</p><div class="related">${l.related.filter(id=>byId[id]).map(id=>`<a class="tag" href="${link(id)}">${escape(byId[id].title)} →</a>`).join('')}</div></section><nav class="lesson-nav" aria-label="相邻文章">${prev?`<a class="button small" href="${link(prev.id)}">← ${escape(prev.title)}</a>`:'<span></span>'}${next?`<a class="button small" href="${link(next.id)}">${escape(next.title)} ${icon('arrow')}</a>`:`<a class="button small" href="#/path">返回学习路线 ${icon('arrow')}</a>`}</nav></article><aside class="toc"><h3>本篇导航 / ON THIS PAGE</h3>${lessonSections(l).map(([id,t])=>`<a href="#${id}" data-action="scroll" data-target="${id}">${escape(t)}</a>`).join('')}<div class="reading-tip">带着真实需求读：<br>它替我解决什么？<br>现有系统能否承担？<br>失败后从哪里排查？</div></aside></div>`;}
function questionMarkup(q,source=true){return `<details class="qa">${source?`<div class="qa-label">${escape(q.lesson.category)} / ${escape(q.lesson.title)}</div>`:''}<summary><span>${escape(q.q)}</span>${icon('down')}</summary><div class="qa-answer">${escape(q.a)}${q.followup?`<p>${escape(q.followup)}</p>`:''}${source?`<a class="qa-source" href="${link(q.lesson.id)}">回到完整讲解 →</a>`:''}</div></details>`;}
function renderQA(){return intro('ANSWERS FOR REAL ENGINEERING QUESTIONS','工程问答，随用随查','围绕架构设计、接入与排障展开。先读解决思路，再回到对应文章理解机制；这里没有题目评分，也不需要提交答案。')+`<div class="qa-tools"><input id="question-search" class="inline-search" type="search" style="width:min(100%,460px)" value="${escape(questionQuery)}" placeholder="例如：重试、超时、向量维度、数据更新…" aria-label="搜索工程问答"><select id="question-category" aria-label="筛选问答分类">${['全部','基础','存储','检索','执行','治理','工程','场景'].map(c=>`<option ${c===questionCategory?'selected':''}>${c}</option>`).join('')}</select><button class="button small" data-action="expand-qa">展开当前解答</button></div><div id="question-results">${questionResults()}</div>`;}
function questionResults(){const term=questionQuery.trim().toLowerCase();const result=allQuestions.filter(q=>(questionCategory==='全部'||q.lesson.category===questionCategory)&&`${q.q} ${q.a} ${q.lesson.title}`.toLowerCase().includes(term));return `<p class="qa-count">${result.length} 个工程问题 · 点击问题查看解释</p><div class="qa-list">${result.length?result.map(q=>questionMarkup(q)).join(''):empty('没有匹配的问题','换一个关键词，或在全站搜索中查找相关概念。')}</div>`;}
function renderCompare(){const a=currentRoute.params.get('a');const b=currentRoute.params.get('b');if(components.some(x=>x.id===a))compareIds[0]=a;if(components.some(x=>x.id===b))compareIds[1]=b;if(compareIds[0]===compareIds[1])compareIds[1]=components.find(x=>x.id!==compareIds[0]).id;return intro('CHOOSE WITH CONTEXT','选型从边界开始','先比较它们是否解决同一个问题，再比较成本和复杂度。不同职责的组件往往需要协作，不能只按名称判断替代关系。')+`<div class="compare-controls"><select class="compare-select" id="compare-a" aria-label="第一个组件">${compareOptions(compareIds[0])}</select><span class="vs">vs.</span><select class="compare-select" id="compare-b" aria-label="第二个组件">${compareOptions(compareIds[1])}</select></div><div id="comparison">${comparison()}</div><p class="compare-help">建议比较：pgvector / Milvus，PostgreSQL / MySQL，Kafka / RocketMQ，Redis / PostgreSQL。先带入自己的数据量、查询方式和运维约束。</p>`;}
function compareOptions(id){return components.map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${escape(c.title)}</option>`).join('');}
function comparison(){const [a,b]=compareIds.map(id=>byId[id]);const list=v=>`<ul>${v.map(x=>`<li>${escape(x)}</li>`).join('')}</ul>`;const rows=[['主要职责',escape(a.summary),escape(b.summary)],['适用需求',list(a.when),list(b.when)],['不宜直接使用',list(a.notFor),list(b.notFor)],['关键机制',list(a.concepts.map(c=>`${c.title}：${c.text}`)),list(b.concepts.map(c=>`${c.title}：${c.text}`))],['工程注意点',list(a.pitfalls),list(b.pitfalls)],['继续阅读',`<a class="text-link" href="${link(a.id)}">查看 ${escape(a.title)} →</a>`,`<a class="text-link" href="${link(b.id)}">查看 ${escape(b.title)} →</a>`]];return `${a.id===b.id?'<div class="storage-warning">当前选择了同一个组件，请选择另一个组件进行比较。</div>':a.category!==b.category?'<div class="storage-warning" style="background:#edf3e7;color:#71845e">这两个组件属于不同能力类别，优先判断协作关系，而非直接替代。</div>':''}<div class="table-scroll"><table class="decision-table compare-table"><thead><tr><th>比较维度</th><th>${escape(a.title)}</th><th>${escape(b.title)}</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function empty(title,desc){return `<div class="empty">${icon('book')}<h3>${escape(title)}</h3><p>${escape(desc)}</p></div>`;}
function renderSaved(){return intro('YOUR OWN FIELD NOTES','我的学习','收藏需要反复查阅的内容，把选型理由写成自己的工程笔记。记录保存在当前浏览器与站点地址下，不会发送到服务器。')+`<div class="saved-tabs">${filterMarkup(['收藏','笔记','已读'],savedTab,'saved-tab')}</div><div id="saved-results">${savedResults()}</div><div class="storage-tools"><p>更换浏览器、端口或清理站点数据前，请先导出备份。导入会合并记录，同篇笔记以导入内容为准。</p><button class="button small" data-action="export">${icon('download')}导出记录</button><button class="button small" data-action="import">${icon('upload')}导入记录</button><input type="file" id="import-file" accept="application/json,.json" hidden></div>`;}
function savedResults(){if(savedTab==='笔记'){const entries=Object.entries(state.notes).filter(([id,t])=>byId[id]&&t.trim());return entries.length?entries.map(([id,t])=>`<article class="saved-note"><h3>${escape(byId[id].title)}</h3><p>${escape(t)}</p><a class="text-link" href="${link(id)}">回到文章编辑 ${icon('arrow')}</a></article>`).join(''):empty('让知识变成自己的理解','在任意文章底部写下笔记，这里会自动汇总。');}const selected=(savedTab==='收藏'?state.bookmarks:state.read).map(id=>byId[id]).filter(Boolean);return selected.length?`<div class="directory-grid">${selected.map(card).join('')}</div>`:empty(savedTab==='收藏'?'还没有收藏文章':'从一篇感兴趣的文章开始',savedTab==='收藏'?'点击文章顶部的“收藏文章”，下次可以快速找到。':'读完文章后可以自愿标记已读，帮助你记录学习位置。');}
const glossary=[
 ['Agent','围绕目标反复获取上下文、调用模型做决策、执行工具并检查结果的程序。可靠性需要由运行时和业务服务共同保证。','agent-basics'],
 ['Workflow / 工作流','由开发者定义步骤与分支的执行流程。可以包含模型节点，也可以作为 Agent 调用的一项工具。','agent-basics'],
 ['RAG / 检索增强生成','在生成前检索外部知识，将有权限访问的证据交给模型，并保留来源引用。它是一条数据与生成链路。','rag-pipeline'],
 ['Embedding / 向量化','把内容映射为数值向量，以距离衡量相似性。模型版本、向量维度和预处理方式必须保持一致。','embedding'],
 ['Chunk / 知识切片','可独立检索的内容单元。切分时需保留标题、来源、版本及访问权限，避免表格与语义被切断。','document-parsing'],
 ['BM25 / 关键词相关性','根据词频、逆文档频率和文档长度等估计文本相关性，适合精确词项、产品型号与编码查询。','elasticsearch'],
 ['Hybrid Search / 混合检索','将关键词与向量等不同召回路径组合，兼顾精确词项和语义表达。最终效果需要用业务问题验证。','milvus'],
 ['RRF / 倒数排名融合','依据候选在各召回列表中的名次进行融合，不需要直接比较不同检索系统的原始分数，也不等于模型重排。','reranker'],
 ['Reranker / 重排','让模型针对问题和候选内容重新评分，只处理召回后的少量候选，改善排序但增加延迟与成本。','reranker'],
 ['Tool Calling / 工具调用','模型返回工具名及参数，由应用校验权限与参数、执行调用，再将结果返回模型。模型不直接获得数据库权限。','tool-calling'],
 ['MCP / 工具接入协议','统一客户端与工具服务交互的协议。它解决接口接入问题，工具的授权、业务幂等和审计仍需设计。','tool-calling'],
 ['Context / 上下文','一次模型请求可见的信息，包括指令、会话、检索证据及工具结果。应控制信息优先级、长度和可信边界。','context-memory'],
 ['Checkpoint / 检查点','执行过程的状态快照，帮助暂停、恢复和人工介入。它不会自动保证外部接口只执行一次。','context-memory'],
 ['Memory / 长期记忆','跨会话保存并检索的偏好与事实，需要考虑更新、冲突、来源、删除及权限，而不是保存全部对话。','context-memory'],
 ['Idempotency / 幂等','同一业务动作重复请求时，不产生重复副作用。通常使用业务幂等键、唯一约束和状态机共同实现。','reliability'],
 ['At-least-once / 至少一次','系统可能重复投递或执行，以减少任务丢失。消费者必须识别重复并妥善处理已经发生的副作用。','rocketmq'],
 ['Trace / 执行链路','一次业务请求从检索到模型调用、工具执行的关联记录。应以同一个请求标识串起服务，并对敏感内容脱敏。','observability'],
 ['Sandbox / 沙箱','受限的代码运行环境，需要控制文件、网络、权限、资源和生命周期。容器化本身不等于完整隔离。','sandbox'],
 ['ACL / 访问控制列表','定义用户或租户能访问哪些文档、记录和工具。知识检索应在召回阶段施加权限过滤。','rag-pipeline'],
 ['Token / 模型计量单元','模型处理文本的切分单位，与汉字、单词不一一对应。上下文限制与费用通常和 Token 数有关。','agent-basics'],
 ['CDC / 变更数据捕获','捕获数据库新增、修改和删除事件，驱动知识索引更新。需要处理同步延迟、删除传播和事件重放。','postgres'],
 ['Outbox / 事务发件箱','在业务事务中同时写业务记录与待发事件，再由后台投递消息，减少数据库成功但消息丢失的问题。','reliability']
];
function renderGlossary(){return intro('A SHARED ENGINEERING VOCABULARY','概念不绕弯，术语随手查','把 Agent 术语翻译成工程语言。点击相关讲解，可以进一步了解它在系统里的具体职责。')+`<div class="glossary-grid">${glossary.map(([t,d,id])=>`<article class="glossary-item"><h3>${escape(t)}</h3><p>${escape(d)}</p><a href="${link(id)}">继续阅读：${escape(byId[id].title)} →</a></article>`).join('')}</div>`;}
function renderNotFound(){return intro('PAGE NOT FOUND','这个页面还不存在','请从学习路线或中间件图鉴中选择一篇文章。')+`<a class="button primary" href="#/path">打开学习路线 ${icon('arrow')}</a>`;}
function searchText(l){return [l.title,l.tagline,l.summary,...l.when,...l.notFor,...l.concepts.map(c=>c.title+' '+c.text),...l.sections.flatMap(s=>[s.title,...(s.paragraphs||[]),...(s.bullets||[])]),...l.qa.map(q=>q.q+' '+q.a),demoSearchText(l.id)].join(' ').toLowerCase();}
const searchIndex=lessons.map(l=>({l,text:searchText(l)}));
function openSearch(){searchReturnFocus=document.activeElement;document.getElementById('overlay').innerHTML=`<div class="modal-backdrop" data-action="backdrop-close"><section class="search-modal" role="dialog" aria-modal="true" aria-label="搜索学习手册"><div class="modal-input-wrap">${icon('search')}<input id="global-search" type="search" aria-label="搜索关键词" placeholder="搜索组件、场景、原理或排障问题…" autocomplete="off"><button class="modal-close" data-action="close-search" aria-label="关闭搜索">ESC</button></div><div class="search-results" id="search-results">${searchResults('')}</div><div class="search-foot">全文搜索 · 包含 ${lessons.length} 篇文章和 ${allQuestions.length} 个问答 · Esc 关闭</div></section></div>`;document.body.style.overflow='hidden';document.getElementById('global-search').focus();}
function closeSearch(restore=true){const has=!!document.querySelector('.search-modal');document.getElementById('overlay').innerHTML='';document.body.style.overflow='';if(has&&restore&&searchReturnFocus?.isConnected)searchReturnFocus.focus();}
function highlight(value,term){if(!term)return escape(value);const terms=term.split(/\s+/).filter(Boolean).map(t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));return escape(value).replace(new RegExp(`(${terms.map(escape).join('|')})`,'ig'),'<mark>$1</mark>');}
function searchResults(query){const term=query.trim().toLowerCase();if(!term)return `<div class="search-hint">试试搜索「幂等」「检索不准」「Spring AI」「工具超时」</div>${['agent-basics','rag-pipeline','reliability','observability'].map(id=>searchResult(byId[id],'')).join('')}`;const terms=term.split(/\s+/);const result=searchIndex.filter(x=>terms.every(t=>x.text.includes(t))).map(x=>({...x,score:terms.reduce((n,t)=>n+(x.l.title.toLowerCase().includes(t)?30:0)+(x.l.tagline.toLowerCase().includes(t)?10:0),0)})).sort((a,b)=>b.score-a.score).slice(0,20);return result.length?`<div class="search-hint">找到 ${result.length}${result.length===20?'（最多展示 20）':''} 篇相关讲解</div>${result.map(x=>searchResult(x.l,term)).join('')}`:'<div class="search-hint">暂无匹配内容。可以缩短关键词，或尝试「超时」「向量」「缓存」。</div>';}
function searchResult(l,term){const question=l.qa.find(q=>term&&`${q.q} ${q.a}`.toLowerCase().includes(term));return `<a class="search-result" href="${link(l.id)}" data-action="search-go"><small>${escape(l.category)} · ${l.minutes} 分钟</small><strong>${highlight(l.title,term)}</strong><p>${highlight((question?question.q+' '+question.a:l.summary).slice(0,115),term)}${(question?question.a:l.summary).length>115?'…':''}</p></a>`;}
async function copyText(text){try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);}else{const e=document.createElement('textarea');e.value=text;e.style.position='fixed';e.style.opacity='0';document.body.append(e);e.select();const ok=document.execCommand('copy');e.remove();if(!ok)throw new Error('copy');}toast('已复制到剪贴板');}catch{toast('浏览器未允许复制，请手动选择内容复制。');}}
function updateLessonActions(id){const readButton=document.querySelector('[data-action="read"]');const bookmark=document.querySelector('[data-action="bookmark"]');if(readButton){const read=state.read.includes(id);readButton.className=`button small ${read?'green':'primary'}`;readButton.innerHTML=`${icon(read?'check':'book')}${read?'已读 · 点击撤销':'标记为已读'}`;}if(bookmark)bookmark.innerHTML=`${icon('bookmark')}${state.bookmarks.includes(id)?'已收藏':'收藏文章'}`;document.getElementById('sidebar-progress').innerHTML=progressMarkup();}
document.addEventListener('click',async e=>{
 const el=e.target.closest('[data-action]');if(!el)return;const {action,id}=el.dataset;
 if(action==='backdrop-close'&&e.target!==el)return;
 if(!['search-go'].includes(action))e.preventDefault();
 if(action==='skip'){document.getElementById('main').focus();document.getElementById('main').scrollIntoView({block:'start'});}
 else if(action==='search')openSearch();
 else if(['close-search','backdrop-close','search-go'].includes(action))closeSearch(action!=='search-go');
 else if(action==='menu'){document.getElementById('sidebar').classList.toggle('open');document.querySelector('.mobile-scrim').classList.toggle('open');el.setAttribute('aria-expanded',document.getElementById('sidebar').classList.contains('open'));}
 else if(action==='close-menu'){document.getElementById('sidebar').classList.remove('open');document.querySelector('.mobile-scrim').classList.remove('open');document.querySelector('.menu-toggle')?.setAttribute('aria-expanded','false');}
 else if(action==='library-filter'){libraryCategory=el.dataset.category;document.querySelectorAll('[data-action="library-filter"]').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',b===el)});document.getElementById('library-results').innerHTML=libraryResults();}
 else if(action==='saved-tab'){savedTab=el.dataset.category;document.querySelectorAll('[data-action="saved-tab"]').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',b===el)});document.getElementById('saved-results').innerHTML=savedResults();}
 else if(action==='read'||action==='bookmark'){const field=action==='read'?'read':'bookmarks';state[field]=state[field].includes(id)?state[field].filter(x=>x!==id):[...state[field],id];save();updateLessonActions(id);toast(action==='read'?(state.read.includes(id)?'已记录阅读进度':'已取消已读标记'):(state.bookmarks.includes(id)?'已加入我的收藏':'已取消收藏'));}
 else if(action==='copy-link')await copyText(location.href);
 else if(action==='copy-code')await copyText(byId[id].sections[Number(el.dataset.index)].code.value);
 else if(action==='scroll'){const target=document.getElementById(el.dataset.target);target?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
 else if(action==='expand-qa'){const list=[...document.querySelectorAll('#question-results details')];const open=list.some(d=>!d.open);list.forEach(d=>d.open=open);el.textContent=open?'收起当前解答':'展开当前解答';}
 else if(action==='export'){const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='agent-handbook-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('学习记录已导出');}
 else if(action==='import')document.getElementById('import-file').click();
});
document.addEventListener('input',e=>{
 if(e.target.id==='global-search')document.getElementById('search-results').innerHTML=searchResults(e.target.value);
 if(e.target.id==='library-search'){libraryQuery=e.target.value;document.getElementById('library-results').innerHTML=libraryResults();}
 if(e.target.id==='question-search'){questionQuery=e.target.value;document.getElementById('question-results').innerHTML=questionResults();document.querySelector('[data-action="expand-qa"]').textContent='展开当前解答';}
 if(e.target.dataset.note){state.notes[e.target.dataset.note]=e.target.value;save();document.getElementById('note-status').textContent=storageAvailable?'已自动保存到本地':'当前无法持久化，请导出备份';}
});
document.addEventListener('change',async e=>{
 if(e.target.id==='question-category'){questionCategory=e.target.value;document.getElementById('question-results').innerHTML=questionResults();document.querySelector('[data-action="expand-qa"]').textContent='展开当前解答';}
 if(e.target.id==='compare-a'||e.target.id==='compare-b'){compareIds[e.target.id==='compare-a'?0:1]=e.target.value;document.getElementById('comparison').innerHTML=comparison();history.replaceState(null,'',`#/compare?a=${encodeURIComponent(compareIds[0])}&b=${encodeURIComponent(compareIds[1])}`);}
 if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw new Error('oversize');const raw=JSON.parse(await file.text());if(raw.version!==1||!Array.isArray(raw.read)||!Array.isArray(raw.bookmarks)||!raw.notes||typeof raw.notes!=='object'||Array.isArray(raw.notes))throw new Error('schema');const imported=sanitizeState(raw);state={...state,read:[...new Set([...state.read,...imported.read])],bookmarks:[...new Set([...state.bookmarks,...imported.bookmarks])],notes:{...state.notes,...imported.notes}};save();render();toast('记录已合并导入');}catch{toast('无法导入：请使用本站导出的 JSON 文件（小于 2 MB）。');}finally{e.target.value='';}}
});
document.addEventListener('keydown',e=>{
 if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();return;}
 if(e.key==='Escape'){closeSearch();document.getElementById('sidebar')?.classList.remove('open');document.querySelector('.mobile-scrim')?.classList.remove('open');document.querySelector('.menu-toggle')?.setAttribute('aria-expanded','false');}
 const modal=document.querySelector('.search-modal');
 if(modal&&e.key==='Tab'){const focusable=[...modal.querySelectorAll('input,button,a[href]')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
 if(modal&&e.key==='Enter'&&document.activeElement.id==='global-search'){const a=modal.querySelector('.search-result');if(a){closeSearch(false);location.hash=a.hash;}}
});
bindDemoEvents({lessons:byId,copyText});
window.addEventListener('hashchange',render);
render();
